    public HandoverDetailView accept(@PathVariable String handoverKey,
                                     @RequestHeader("X-Actor-Id") String actor,
                                     @RequestBody HandoverAcceptRequest req) {
        return service.accept(handoverKey, actor, req);
    }
}

